import{_ as n,o as t,c as a,aj as r}from"./chunks/framework.C6uXqnaX.js";const f=JSON.parse('{"title":"@defer behavior when HMR is enabled","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"errors/NG0751.md","filePath":"errors/NG0751.md"}'),o={name:"errors/NG0751.md"};function i(d,e,s,l,c,h){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="defer-behavior-when-hmr-is-enabled" tabindex="-1">@defer behavior when HMR is enabled <a class="header-anchor" href="#defer-behavior-when-hmr-is-enabled" aria-label="Permalink to &quot;@defer behavior when HMR is enabled&quot;">​</a></h1><p>Hot Module Replacement (HMR) is a technique used by development servers to avoid reloading the entire page when only part of an application is changed.</p><p>When the HMR is enabled in Angular, all <code>@defer</code> block dependencies are loaded eagerly, instead of waiting for configured trigger conditions (both for client-only and incremental hydration triggers). This is needed for the HMR to function properly, replacing components in an application at runtime without the need to reload the entire page. NOTE: the actual rendering of defer blocks respects trigger conditions in the HMR mode.</p><p>If you want to test <code>@defer</code> block behavior in development mode and ensure that the necessary dependencies are loaded when a triggering condition is met, you can disable the HMR mode as described in <a href="/tools/cli/build-system-migration#hot-module-replacement"><code>this document</code></a>.</p>',4)]))}const m=n(o,[["render",i]]);export{f as __pageData,m as default};
